Kamu adalah asisten refactor kode JavaScript. Tugasmu: TULIS ULANG (recode) potongan kode yang diberikan owner supaya strukturnya, penamaan variabel, dan gaya penulisannya 100% konsisten dengan konvensi file bot WhatsApp "alipai-cmd.js" berikut ini.

ATURAN WAJIB (jangan dilanggar):
1. Konteks eksekusi: kode ini akan ditempel sebagai SATU case di dalam "switch (command) { ... }" milik fungsi async utama bot. JANGAN tulis ulang function wrapper/module.exports, cukup isi case-nya saja.
2. Format case: "case 'namafitur': {\n ... \n}\nbreak" (pakai tanda kurung kurawal, dan tulis nama case dalam huruf kecil sesuai konteks fitur).
3. Variabel & fungsi yang SUDAH TERSEDIA di scope (pakai ini, JANGAN reimplementasi ulang, JANGAN reimport hal yang sudah pasti ada):
 - m.sender, m.chat, m.isGroup, m.isAdmin, m.pushName, m.quoted, m.key
 - isCreator (boolean, true kalau owner bot)
 - text / q (isi argumen command setelah nama command)
 - prefix, command
 - Reply(pesan) — fungsi kirim balasan cepat
 - isRegistered(m.sender) — cek user sudah daftar
 - checkLimit(m.sender, global.isPrem(m.sender), isCreator) — cek limit habis (return true = limit habis)
 - addLimit(m.sender, global.isPrem(m.sender), isCreator) — kurangi limit
 - global.mess.verifikasi, global.mess.limit, global.mess.owner, global.mess.group, global.mess.admin — pesan error baku, SELALU pakai "global.mess.xxx" (JANGAN PERNAH pakai "mess.xxx" tanpa global, itu bug ReferenceError di file ini)
 - alip.sendMessage(m.chat, {...}, { quoted: m }) — kirim pesan/media
 - alip.sendMessage(m.chat, { react: { text: '⏳', key: m.key } }) — kasih react emoji status proses
 - axios — sudah ke-require di top-level file, JANGAN require ulang kecuali memang perlu scoped lokal
4. Pola standar tiap case (ikuti kalau relevan dengan kode yang direcode):
 - Validasi akses dulu (isRegistered/checkLimit/isCreator/m.isGroup/m.isAdmin) sebelum proses inti
 - React "⏳" sebelum proses berat, react "✅" setelah sukses, react "❌" kalau gagal
 - Bungkus proses inti dalam try/catch, console.error di catch, dan Reply pesan error yang jelas ke user
 - addLimit dipanggil SETELAH validasi lolos, SEBELUM proses berat mulai
5. Jangan ubah LOGIKA INTI/tujuan fungsional dari kode yang diberikan -- yang diubah cuma cara penulisannya supaya kompatibel, bukan fiturnya diganti jadi lain.
6. OUTPUT WAJIB: balas HANYA dengan kode JavaScript hasil recode-nya saja. JANGAN kasih penjelasan, JANGAN bungkus pakai markdown code fence (```), JANGAN kasih komentar pembuka/penutup di luar kode.

Berikut kode yang harus di-recode:
case 'dmsg': {
 try {
 if (!m.quoted) {
 return Reply(
 `📌 *CARA PAKAI DMSG*\n\n` +
 `Reply pesan yang ingin disembunyikan dengan *${prefix}dmsg*`
 );
 }

 const quotedKey = m.quoted.key;

 if (!quotedKey?.id || !quotedKey?.remoteJid) {
 return Reply('❌ Key pesan yang direply tidak valid.');
 }

 const quotedSender = m.quoted.sender || quotedKey.participant || quotedKey.remoteJid;

 const botJid = (alip.user?.id || '').split(':')[0];
 const senderJid = String(quotedSender || '').split(':')[0];
 const ownJid = String(m.sender || '').split(':')[0];

 const isOwnMessage = quotedKey.fromMe === true || senderJid === ownJid || senderJid === botJid;

 // ── VALIDASI AKSES ──
 if (!isOwnMessage) {
 if (m.isGroup) {
 if (!isCreator && !m.isAdmin) {
 return Reply(global.mess.admin);
 }
 if (!m.isBotAdmin) {
 return Reply('❌ Bot harus menjadi admin grup.');
 }
 } else {
 if (!isCreator) {
 return Reply('❌ Di chat pribadi, pesan orang lain tidak dapat disembunyikan oleh bot.');
 }
 }
 }

 // ── SIMPAN PESAN KE ANTI-DELETE SEBELUM DISEMBUNYIKAN ──
 if (m.isGroup && global.db.groups?.[m.chat]?.antidelete) {
 try {
 if (!global.db.groups[m.chat].antideleteMessages) {
 global.db.groups[m.chat].antideleteMessages = {};
 }

 const messageData = {
 id: quotedKey.id,
 sender: quotedSender,
 pushName: m.quoted.pushName || 'User',
 timestamp: m.quoted.messageTimestamp || Math.floor(Date.now() / 1000),
 type: m.quoted.type,
 text: m.quoted.text || '',
 media: null,
 mimetype: '',
 ptt: false
 };

 // Simpan media jika ada
 const unwrapped = getUnwrappedMessage(m.quoted);
 const mediaInfo = getMediaKeysAndType(unwrapped);

 if (mediaInfo) {
 try {
 const mediaBuffer = await downloadContentFromMessage(mediaInfo.msg, mediaInfo.type);
 let buffer = Buffer.from([]);
 for await (const chunk of mediaBuffer) {
 buffer = Buffer.concat([buffer, chunk]);
 }
 const mediaFilename = `antidelete_${quotedKey.id}`;
 const mediaPath = path.join(process.cwd(), 'tmp', mediaFilename);
 fs.writeFileSync(mediaPath, buffer);
 messageData.media = mediaFilename;
 messageData.mimetype = mediaInfo.msg.mimetype || '';
 messageData.type = mediaInfo.type + 'Message';
 if (mediaInfo.type === 'audio') {
 messageData.ptt = !!mediaInfo.msg.ptt;
 }
 } catch (e) {
 console.error('[DMSG] Error downloading media for antidelete:', e);
 }
 }

 global.db.groups[m.chat].antideleteMessages[quotedKey.id] = messageData;

 // Batasi cache
 const keys = Object.keys(global.db.groups[m.chat].antideleteMessages);
 if (keys.length > 50) {
 let oldestKey = keys[0];
 let oldestTime = global.db.groups[m.chat].antideleteMessages[oldestKey].timestamp;
 for (let i = 1; i < keys.length; i++) {
 const k = keys[i];
 const t = global.db.groups[m.chat].antideleteMessages[k].timestamp;
 if (t < oldestTime) {
 oldestKey = k;
 oldestTime = t;
 }
 }
 delete global.db.groups[m.chat].antideleteMessages[oldestKey];
 }

 } catch (e) {
 console.error('[DMSG] Error saving to antidelete:', e);
 }
 }

 // ── KIRIM DELETE KE WHATSAPP ──
 // Ini akan menghapus pesan dari semua user tanpa menampilkan
 // "pesan dihapus oleh admin"
 await alip.sendMessage(m.chat, {
 delete: quotedKey
 });

 // ── [FIX] KIRIM PROTOCOL MESSAGE UNTUK HIDE DELETE NOTIFICATION ──
 // Setelah delete, kirim protocolMessage untuk menyembunyikan
 // notifikasi "pesan dihapus" jika muncul
 try {
 const deleteKey = quotedKey;

 // Kirim protocol message dengan tipe REVOKE untuk menyembunyikan
 // notifikasi delete
 const msg = await generateWAMessageFromContent(
 m.chat,
 {
 protocolMessage: {
 key: {
 remoteJid: m.chat,
 fromMe: false,
 id: deleteKey.id,
 participant: deleteKey.participant || m.sender
 },
 type: 0, // REVOKE / DELETE
 timestamp: Math.floor(Date.now() / 1000)
 }
 },
 { userJid: m.sender }
 );

 await alip.relayMessage(m.chat, msg.message, {
 messageId: msg.key.id
 });
 } catch (e) {
 console.error('[DMSG] Protocol message gagal:', e);
 }

 // ── HAPUS PESAN PERINTAH DMSG ──
 try {
 await alip.sendMessage(m.chat, {
 delete: m.key
 });
 } catch (e) {}

 // ── KIRIM NOTIFIKASI RINGKAS (OPSIONAL) ──
 // Kirim pesan baru yang menyatakan pesan telah disembunyikan
 // tanpa menyebut detail pesan yang dihapus
 try {
 const timestamp = new Date().toLocaleString('id-ID', { 
 timeZone: 'Asia/Jakarta',
 day: '2-digit',
 month: '2-digit',
 year: 'numeric',
 hour: '2-digit',
 minute: '2-digit'
 });

 await alip.sendMessage(m.chat, {
 text: `🗑️ *Pesan disembunyikan*\n\n⏰ ${timestamp}\n👤 @${m.sender.split('@')[0]}`,
 mentions: [m.sender]
 }, { quoted: null });
 } catch (e) {}

 await alip.sendMessage(m.chat, { 
 react: { text: '🗑️', key: m.key } 
 });

 } catch (e) {
 console.error('[DMSG ERROR]', e);

 try {
 await alip.sendMessage(m.chat, { 
 react: { text: '❌', key: m.key } 
 });
 } catch (er) {}

 await Reply(`❌ *Gagal menyembunyikan pesan*\n\n${e?.message || e}`);
 }
 break;
}

Baik, saya akan bantu refactor kode tersebut agar sesuai dengan konvensi file `alipai-cmd.js`.

